const villagers=[
{id:'mira',name:'Mira',kind:'Blomsterälva',color:'#aa8cba',unlock:0,house:'Blomsterstugan',hello:'Välkommen, granne! Jag drömmer om en by där alla känner sig hemma. Ska vi lära känna varandra?',task:'En första vän',desc:'Hälsa på Mira och välkomna henne till byn.',reward:20},
{id:'tagge',name:'Tagge',kind:'Igelkott och trädgårdsmästare',color:'#98795d',unlock:0,house:'Lövboet',hello:'Hej! Jag bakar bärpaj till våra grannar. Har du två bär över? Du kan odla dem i gläntan eller köpa på torget.',task:'Bärpaj till grannarna',desc:'Ge Tagge 2 bär från din korg.',reward:30},
{id:'tilda',name:'Tilda',kind:'Mus och stigfinnare',color:'#a5a9ad',unlock:1,house:'Ekollonhuset',hello:'Vilken mysig by! Jag vill hitta en trygg stig till Näckrosdammen. Kan du fullfölja ett race där efter att vi har pratat?',task:'En trygg stig',desc:'Prata med Tilda, fullfölj sedan ett race i Näckrosdammen.',reward:40},
{id:'vide',name:'Vide',kind:'Lyktälva',color:'#7aab9d',unlock:3,house:'Ljusgläntans hus',hello:'Jag vill lysa upp våra kvällar. Om du hjälper den vilsekomna eldflugan kan jag bjuda in hennes familj till torget.',task:'Ljus på torget',desc:'Slutför äventyret Den vilsekomna eldflugan och berätta för Vide.',reward:50}
];
function ensureVillage(){ensureGarden();if(!state.village){state.village={residents:['mira','tagge'],talked:[],done:[],friendship:{},pondTrips:0,tildaStart:null};save()}}
function villageVisit(id){ensureVillage();if(!state.village.residents.includes(id))return false;if(!state.village.talked.includes(id))state.village.talked.push(id);if(id==='tilda'&&state.village.tildaStart===null)state.village.tildaStart=state.village.pondTrips;save();return true}
function villageReady(id){const v=state.village;if(!v||!v.residents.includes(id)||v.done.includes(id)||!v.talked.includes(id))return false;return id==='mira'||id==='tagge'&&state.garden.berries>=2||id==='tilda'&&v.tildaStart!==null&&v.pondTrips>v.tildaStart||id==='vide'&&storyProgress('firefly').done}
function villageHelp(id){if(!villageReady(id))return false;const v=villagers.find(v=>v.id===id);if(id==='tagge')state.garden.berries-=2;state.village.done.push(id);state.village.friendship[id]=1;state.coins+=v.reward;state.trust+=5;save();return true}
function moveIn(id){ensureVillage();const v=villagers.find(v=>v.id===id);if(!v||state.village.residents.includes(id)||state.village.done.length<v.unlock)return false;state.village.residents.push(id);save();return true}
function buyVillageBerries(){ensureVillage();if(state.coins<10)return false;state.coins-=10;state.garden.berries+=2;save();return true}
function residentArt(id){const v=villagers.find(v=>v.id===id);let art='';if(id==='tagge')art='<path d="M18 78L9 61 24 58 16 42 33 46 33 27 47 39 57 22 65 39 81 29 79 49 97 44 91 65 104 73Z" fill="#81614a"/><ellipse cx="59" cy="74" rx="37" ry="24" fill="#b69773"/><path d="M70 63Q93 62 106 80Q88 92 74 87" fill="#e5c8a0"/><circle cx="91" cy="75" r="3" fill="#334337"/><circle cx="106" cy="80" r="4" fill="#334337"/><path d="M39 96h15m20 0h13" stroke="#70553f" stroke-width="5" stroke-linecap="round"/>';else if(id==='tilda')art='<path d="M38 90Q5 102 12 69" fill="none" stroke="#d5b0a3" stroke-width="4"/><ellipse cx="62" cy="78" rx="25" ry="28" fill="#a5a9ad"/><circle cx="48" cy="36" r="15" fill="#a5a9ad"/><circle cx="81" cy="36" r="15" fill="#a5a9ad"/><g fill="#dfbbb2"><circle cx="48" cy="36" r="10"/><circle cx="81" cy="36" r="10"/></g><ellipse cx="65" cy="57" rx="23" ry="25" fill="#b8bcbd"/><circle cx="57" cy="54" r="3"/><circle cx="74" cy="54" r="3"/><circle cx="66" cy="66" r="4" fill="#ce968e"/><path d="M46 79L83 77 80 92 49 95Z" fill="#b9a56c"/>';else art=`<g fill="#e9f1e5" stroke="#b3d6c6"><ellipse cx="34" cy="66" rx="14" ry="28" transform="rotate(-30 34 66)"/><ellipse cx="86" cy="66" rx="14" ry="28" transform="rotate(30 86 66)"/></g><path d="M46 64L32 103H89L75 64" fill="${v.color}"/><path d="M40 42Q37 12 60 13Q86 14 81 48" fill="${id==='mira'?'#8a563f':'#c8af72'}"/><ellipse cx="60" cy="45" rx="20" ry="24" fill="${id==='mira'?'#b9805c':'#efc6a1'}"/><path d="M40 38Q55 42 61 22Q74 28 81 38" fill="${id==='mira'?'#8a563f':'#c8af72'}"/><circle cx="53" cy="45" r="2.5"/><circle cx="68" cy="45" r="2.5"/><path d="M53 56Q60 62 68 56" fill="none" stroke="#784e43" stroke-width="2"/>${id==='mira'?'<g fill="#f4dda0"><circle cx="43" cy="25" r="6"/><circle cx="58" cy="20" r="6"/><circle cx="74" cy="25" r="6"/></g>':'<path d="M88 62V94" stroke="#866e46" stroke-width="3"/><rect x="80" y="59" width="17" height="23" rx="6" fill="#f2db8f"/>'}`;return `<svg viewBox="0 0 120 120" aria-hidden="true"><ellipse cx="60" cy="107" rx="39" ry="6" fill="#42633320"/>${art}</svg>`}
// The map of Älvbyn (survey 6: "the signs sit a bit wrong, and tapping the square should take
// you to the square"). Every place is a real button with a wooden signpost beside it, joined to
// the square by dirt paths. Places sit at a centre in percent of the map, the same on phone and
// the paths drawn in the ground always meet them. Phones get a taller map with their own spots.
const villageSpots={square:[50,58],shop:[50,21],home:[50,93],mira:[17,29],tagge:[83,29],tilda:[17,73],vide:[83,73]};
const villageSpotsPhone={square:[50,53],shop:[50,13],home:[50,94],mira:[23,31],tagge:[77,31],tilda:[23,74],vide:[77,74]};
function villageMapPlaces(){ensureVillage();const v=state.village;return [
 {id:'square',sign:'Bytorget',label:'Gå till bytorget',go:'square'},
 {id:'shop',sign:'Butiken',label:'Gå till butiken',go:'tab:shop'},
 {id:'home',sign:'Till gläntan',label:'Gå hem till gläntan',go:'tab:home'},
 ...villagers.map(r=>v.residents.includes(r.id)?{id:r.id,sign:r.house,label:'Hälsa på '+r.name,go:'talk:'+r.id}:{id:r.id,sign:'Ledig tomt',label:'Ledig tomt – vem vill flytta in?',go:'card:'+r.id,empty:true})]}
// Where a tap on the map takes you: another place (with the hop from resor.js), a neighbour's
// door, or down the page to the square's stalls or the card of whoever may move in.
function villageGo(go){const [k,id]=String(go).split(':');
 if(k==='tab'){tab=id;render();return true}
 if(k==='talk'){if(!villageVisit(id))return false;showVillageDialog(id);return true}
 const el=k==='square'?$('#villageTorget'):k==='card'?document.querySelector(`[data-card="${id}"]`):null;if(!el)return false;
 el.scrollIntoView({behavior:'smooth',block:k==='square'?'start':'center'});el.classList.remove('villageArrive');void el.offsetWidth;el.classList.add('villageArrive');return true}
// A wooden signpost: a plank on a post, drawn in SVG behind the name so any length fits.
function villageSign(text,arrow=false){return `<span class="villageSign${arrow?' arrow':''}"><span class="signBoard"><svg viewBox="0 0 100 40" preserveAspectRatio="none" aria-hidden="true"><path d="${arrow?'M3 5H84L98 20L84 35H3Q1 20 3 5Z':'M4 5Q50 1 96 4Q99 20 97 35Q50 39 3 36Q1 20 4 5Z'}" fill="#c99a63" stroke="#7d5535" stroke-width="2.5" vector-effect="non-scaling-stroke"/><path d="M9 14Q45 11 ${arrow?'80':'90'} 13M8 27Q50 30 ${arrow?'82':'91'} 26" fill="none" stroke="#ad7d4b" stroke-width="1.3" vector-effect="non-scaling-stroke"/></svg><b>${text}</b></span><svg class="signPost" viewBox="0 0 24 30" aria-hidden="true"><path d="M9.5 0H14.5L15 27H9Z" fill="#8d6440"/><path d="M11 3V25" stroke="#a7794f" stroke-width="1.4"/><path d="M1 30Q5 21 8 28Q10 19 12 27Q15 19 17 28Q20 22 23 30Z" fill="#6f9e4f"/></svg></span>`}
function villagePlaza(){const cob=[[30,52],[46,40],[150,40],[170,56],[38,80],[160,82],[70,94],[132,96],[100,30],[62,30],[140,28]];return `<svg viewBox="0 0 200 120" aria-hidden="true"><ellipse cx="100" cy="64" rx="97" ry="53" fill="#d2c497"/><ellipse cx="100" cy="62" rx="90" ry="47" fill="#ebe2c3"/><g fill="#ddd1a8">${cob.map(([x,y])=>`<ellipse cx="${x}" cy="${y}" rx="7" ry="4"/>`).join('')}</g><ellipse cx="100" cy="64" rx="31" ry="17" fill="#b9ad86"/><ellipse cx="100" cy="62" rx="27" ry="13.5" fill="#7fa864"/><g fill="#f2a6b8"><circle cx="86" cy="60" r="4"/><circle cx="110" cy="56" r="4"/></g><g fill="#fff3c8"><circle cx="98" cy="66" r="4"/><circle cx="118" cy="64" r="3.5"/></g><g fill="#c6a7e0"><circle cx="100" cy="54" r="3.5"/><circle cx="84" cy="68" r="3"/></g><circle cx="98" cy="66" r="1.5" fill="#e2b552"/><path d="M146 92h26M150 92v6M168 92v6" stroke="#8d6440" stroke-width="3.5" stroke-linecap="round"/></svg>`}
// The ground: hills, trees in the corners and a dirt path from the square to every place.
// A house stands on the outer half of its plot, so its path ends at the door (dx, dy from the centre).
function villagePathD(spots,[dx,dy]){const [sx,sy]=spots.square,P=([x,y])=>`${x*10} ${y*6}`;return Object.entries(spots).filter(([k])=>k!=='square').map(([k,[x,y]])=>{const house=villagers.some(v=>v.id===k),to=k==='home'?[x,100]:house?[x<50?x-dx:x+dx,y+dy]:[x,y],mid=[(sx+to[0])/2,(sy+to[1])/2+(to[1]<sy?6:-4)];return `M${P([sx,sy])}Q${P(mid)} ${P(to)}`}).join('')}
function villageGround(){const paths=(d,cls)=>`<g class="villagePaths ${cls}" fill="none" stroke-linecap="round"><path d="${d}" stroke="#d6c899"/><path d="${d}" stroke="#e9dfba" class="inner"/></g>`;
 return `<svg class="gardenBackdrop villageGround" viewBox="0 0 1000 600" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="villageSky" x2="0" y2="1"><stop stop-color="#cfe3d6"/><stop offset=".3" stop-color="#e9eccc"/></linearGradient></defs><rect width="1000" height="600" fill="url(#villageSky)"/><path d="M0 120Q180 60 380 110T740 90T1000 105V600H0Z" fill="#a8c795"/><path d="M0 175Q260 120 520 165T1000 150V600H0Z" fill="#bcd5a6"/><g fill="#a9c893"><ellipse cx="300" cy="470" rx="140" ry="40"/><ellipse cx="760" cy="300" rx="120" ry="34"/></g>${paths(villagePathD(villageSpots,[5.5,0]),'wide')}${paths(villagePathD(villageSpotsPhone,[9.5,3]),'narrow')}<g fill="#6c9862"><circle cx="20" cy="70" r="90"/><circle cx="120" cy="10" r="70"/><circle cx="985" cy="70" r="90"/><circle cx="880" cy="10" r="70"/><circle cx="-10" cy="560" r="80"/><circle cx="1010" cy="560" r="80"/></g><g fill="#5c8a55"><circle cx="60" cy="40" r="40"/><circle cx="940" cy="40" r="40"/></g><g fill="#f3e9b5"><circle cx="300" cy="300" r="5"/><circle cx="690" cy="190" r="4"/><circle cx="640" cy="540" r="5"/><circle cx="360" cy="560" r="4"/><circle cx="230" cy="520" r="4"/><circle cx="780" cy="520" r="5"/></g><g fill="#f2b6c4"><circle cx="315" cy="310" r="4"/><circle cx="655" cy="548" r="4"/><circle cx="700" cy="200" r="3"/></g></svg>`}
function villageMapHTML(){const village=state.village,at=id=>`style="--x:${villageSpots[id][0]};--y:${villageSpots[id][1]};--px:${villageSpotsPhone[id][0]};--py:${villageSpotsPhone[id][1]}"`,places=villageMapPlaces(),place=id=>places.find(p=>p.id===id);
 return `<section class="villageMap" aria-label="Älvbyns hus och invånare">${villageGround()}${typeof seasonOverlayHTML==='function'?seasonOverlayHTML():''}`
 +`<button class="villagePlace villageSquare" data-go="square" aria-label="${place('square').label}" ${at('square')}>${villagePlaza()}${villageSign(place('square').sign)}<span id="squareLights" class="${village.done.includes('vide')?'lit':''}" aria-hidden="true">✦ ✧ ✦ ✧</span></button>`
 +`<button class="villagePlace villageShop" data-go="tab:shop" aria-label="${place('shop').label}" ${at('shop')}>${typeof placeArt==='function'?placeArt('shop'):''}${villageSign(place('shop').sign)}</button>`
 +`<button class="villagePlace villageWayHome" data-go="tab:home" aria-label="${place('home').label}" ${at('home')}>${villageSign(place('home').sign,true)}</button>`
 +villagers.map((v,i)=>{const p=place(v.id),joined=!p.empty;return `<div class="villagePlot plot${i} ${villageSpots[v.id][0]<50?'west':'east'}" ${at(v.id)}><button class="villagePlace villageHouse${joined?'':' empty'}" data-go="${p.go}" aria-label="${p.label}"><span class="houseArt">${gardenArt('house')}</span>${villageSign(p.sign)}</button>${joined?`<button class="villager walker${i}" data-talk="${v.id}" aria-label="Prata med ${v.name}">${residentArt(v.id)}</button>`:''}</div>`}).join('')
 +`</section>`}
function renderVillage(){ensureVillage();const village=state.village;$('#content').innerHTML=`<div class="sectionHead"><div><div class="eyebrow">GRANNAR, VÄNSKAP OCH SMÅ ÄVENTYR</div><h2>Välkommen till Älvbyn</h2></div><button class="outline" id="villageHome">← Din glänta</button></div><p class="gardenLead">${village.residents.length} invånare · ${village.done.length} slutförda grannuppdrag · en plats där alla får höra hemma.</p>${villageMapHTML()}<section id="villageDialog" class="editor villageDialog" aria-live="polite"><h3>En hälsning kan bli början på en vänskap</h3><p>Tryck på ett hus eller en granne på kartan, eller välj Prata nedanför. Hjälp grannarna så vill fler flytta hit.</p></section><div class="villageCards">${villagers.map(v=>{const joined=village.residents.includes(v.id),can=village.done.length>=v.unlock;return `<article class="quest" data-card="${v.id}"><div class="residentPortrait">${residentArt(v.id)}</div><h3>${v.name}</h3><div class="eyebrow">${v.kind}</div><p>${joined?(village.done.includes(v.id)?'♥ Ni är vänner – du har hjälpt din granne.':v.desc):'Flyttar gärna in efter '+v.unlock+' slutförda grannuppdrag. Framsteg: '+Math.min(v.unlock,village.done.length)+' / '+v.unlock}</p><button class="${joined?'outline':'primary'}" ${joined?'data-talk':'data-move'}="${v.id}" ${!joined&&!can?'disabled':''}>${joined?'Prata med '+v.name:can?'Välkomna '+v.name:'Lär känna byn först'}</button></article>`}).join('')}</div><div id="villageTorget">${typeof festivalHTML==='function'?festivalHTML():''}<section class="editor villageMarket"><h3>Torgets lilla handelsbod</h3><p>Två bär för 10 daggdroppar. Du kan också odla gratis i din glänta.</p><p>Din korg: ${state.garden.berries} bär · Din börs: ${state.coins} daggdroppar</p><button class="primary" id="buyVillageBerries" ${state.coins<10?'disabled':''}>Köp 2 bär · 10 ✦</button><button class="outline" id="villageAstrid">Hälsa på Astrid på torget</button><div id="villageRoyal"></div></section></div>`;$('#villageHome').onclick=()=>{tab='home';render()};document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>villageGo(b.dataset.go));document.querySelectorAll('[data-talk]').forEach(b=>b.onclick=()=>{villageVisit(b.dataset.talk);showVillageDialog(b.dataset.talk)});document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{if(moveIn(b.dataset.move)){renderVillage();showVillageDialog(b.dataset.move);toast('En ny granne har flyttat in!')}});$('#buyVillageBerries').onclick=()=>{if(buyVillageBerries()){sidebar();renderVillage();toast('Två bär lagda i korgen.')}};$('#villageAstrid').onclick=()=>{$('#villageRoyal').innerHTML='<img src="assets/astrid-portrait.webp" alt="Astrid på torget"><p>”Det är er vänlighet som gör den här byn till ett hem. Tack för att ni tar hand om varandra!”</p>'};if(typeof wireFestival==='function')wireFestival()}
function showVillageDialog(id){const v=villagers.find(v=>v.id===id);if(!v||!state.village.residents.includes(id))return;villageVisit(id);const done=state.village.done.includes(id),ready=villageReady(id);$('#villageDialog').innerHTML=`<div class="dialogPortrait">${residentArt(id)}</div><div><h3>${v.name} · ${v.kind}</h3><p>”${done?{mira:'Vad fint att se dig igen! Blommorna trivs när vänner samlas.',tagge:'Pajen blev underbar. Du är alltid välkommen till mitt lövbo!',tilda:'Nu hittar alla tryggt till dammen. Tack, stigvän!',vide:'Titta hur torget glittrar! Eldflugorna känner sig hemma här.'}[id]:v.hello}”</p>${done?'<p>♥ Grannhjälp slutförd</p>':`<strong>${v.task}</strong><p>${v.desc}</p><p>Belöning: ${v.reward} daggdroppar · 5 förtroende hos Astrid</p><button class="primary" id="helpNeighbour" ${!ready?'disabled':''}>${ready?(id==='tagge'?'Ge 2 bär':'Hjälp '+v.name):'Inte klart ännu'}</button>${id==='tilda'?'<button class="outline" id="neighbourRace">Till Näckrosdammen →</button>':id==='vide'?'<button class="outline" id="neighbourAdventure">Till äventyren →</button>':''}`}</div>`;if($('#helpNeighbour'))$('#helpNeighbour').onclick=()=>{if(villageHelp(id)){sidebar();renderVillage();showVillageDialog(id);toast(v.name+' tackar dig! Byn växer med er vänskap.')}};if($('#neighbourRace'))$('#neighbourRace').onclick=()=>{chosen=0;tab='race';render()};if($('#neighbourAdventure'))$('#neighbourAdventure').onclick=()=>{tab='adventure';render()};$('#villageDialog').scrollIntoView({behavior:'smooth',block:'nearest'})}
